-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["a80415744d66c987"] = { "Ci alzammo con il sole. Barnil cominciò a preparare la colazione. Notai che l'attenzione di Ajeck era alquanto distratta. Il cammino della giornata sarebbe stato lungo e la caccia ci avrebbe portati vicino al pericolo. Una mancanza di concentrazione poteva facilmente causare un incidente. Eppure Ajeck sembrava incapace di distogliere lo sguardo da Barnil, che se ne stava sulla riva del fiume a sciacquare la sua gavetta.", "." },
  ["a812cdacf6119792"] = { "Unite sotto un unico stendardo, le tribù umane svilupparono una cultura forte e ottimista. Thoradin, il re di Arathor, sapeva che i misteriosi elfi delle terre del nord erano costantemente assediati dai troll, ma si rifiutava di mettere a rischio la sicurezza del suo popolo per difendere degli stranieri schivi. Passarono molti mesi, mentre dal nord giungevano voci della presunta sconfitta degli elfi. Solo quando stremati ambasciatori di Quel'Thalas raggiunsero Strom, Thoradin capì quanto fosse davvero grande la minaccia dei troll.", "." },
  ["a87855bfb17b9c85"] = { "I pochi elfi della notte sopravvissuti all'orribile esplosione si radunarono su zattere rozzamente costruite e si diressero lentamente verso l'unica terra in vista. In qualche modo, per grazia di Elune, Malfurion, Tyrande e Cenarius erano sopravvissuti alla Grande Separazione. Gli eroi, stremati, accettarono di guidare gli altri sopravvissuti e di fondare una nuova patria per il loro popolo.", "." },
  ["a881de3e6a771cdd"] = { "Illidan accettò e partì subito per distruggere il Trono di Ghiaccio, lo scrigno di cristallo gelato in cui risiedeva lo spirito del Re dei Lich. Illidan sapeva che gli sarebbe servito un manufatto possente per distruggere il Trono di Ghiaccio. Grazie alla conoscenza ricavata dai ricordi di Gul'dan, Illidan decise di cercare la Tomb of Sargeras e di impossessarsi dei resti del Titano Oscuro.", "." },
  ["a88dbe9ad9c283f6"] = { "In breve tempo, quella razza spirituale si trasformò in un popolo assetato di sangue. Kil'jaeden spinse allora Ner'zhul e il suo popolo a compiere l'ultimo passo: abbandonarsi completamente alla ricerca della morte e della guerra. Ma il vecchio sciamano, intuendo che il suo popolo sarebbe rimasto schiavo dell'odio per sempre, in qualche modo resistette al comando del demone.", "." },
  ["a8aa2a9489f9a5dd"] = { "Valik,\nsorveglia lo schiavo fino al nostro ritorno. Non è più sicuro tenere qui QUELLA COSA. La sposteremo a nord, più lontano da ogni possibilità di essere vista.\n\nSono animali, ma pur sempre animali brutali: se fossero abbastanza numerosi, avremmo motivo di preoccuparci. Meglio nascondere del tutto qualsiasi segno che possa provocarli. L'ultima cosa che vogliamo è dar loro un motivo per radunarsi e attaccarci in forze.", "." },
  ["a8b0b486a9785c7a"] = { "Per la barba di Magni, c'è molto da discutere e poco tempo per farlo, {name}. Raggiungimi a ⟦Anvilmar=Forgiamara⟧, che domina la ⟦Coldridge Valley=Valle Crestafredda⟧, appena puoi. Dobbiamo cominciare.\n\nPotrei raccontarti un mucchio di cose per metterti al passo, ma niente di tutto ciò riguarda noi... per ora. Quello su cui dobbiamo concentrarci è l'impugnatura di un'ascia, il peso della nostra armatura e l'odore del nostro sudore che ci cola giù dalla fronte mentre combattiamo i nemici. Cominceremo da qui.\n\n-Thran Khorman, istruttore dei guerrieri", "." },
  ["a8d6c46ef5e70d10"] = { "Quando la follia di Sargeras ebbe consumato le ultime vestigia del suo spirito valoroso, egli era ormai convinto che fossero gli stessi Titani i responsabili del fallimento della creazione. Deciso, infine, a distruggere le loro opere in tutto l'universo, risolse di formare un esercito inarrestabile che avrebbe dato alle fiamme l'universo fisico.", "." },
})
